Use the cached Amount Outstanding and Over Due Days values from Sheet1. Mark negative outstanding as Prepaid, blank overdue days as empty, and otherwise apply the <90 day rule. Write the resulting text values into J6:J10.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet1"]
vws = vals["Sheet1"]

def is_blank(x):
    return x is None or (isinstance(x, str) and x.strip() == "")

for r in range(6, 11):
    outstanding = vws.cell(row=r, column=8).value  # H
    overdue_days = vws.cell(row=r, column=9).value  # I

    if not is_blank(outstanding) and isinstance(outstanding, (int, float)) and outstanding < 0:
        remark = "Prepaid"
    elif is_blank(overdue_days):
        remark = None
    else:
        try:
            days = float(overdue_days)
        except (TypeError, ValueError):
            days = None

        if days is None:
            remark = None
        elif days < 90:
            remark = "Call Customer"
        else:
            remark = "Bad Debts"

    ws.cell(row=r, column=10).value = remark
    print(r, outstanding, overdue_days, remark)

wb.save(OUT)
